/* generated by tools/block-demos/build.js – block id → caption of its demo clip */
window.VX = window.VX || {};
VX.docClips = {"accelerometer":"Accelerometer reads how the phone is tilted. On a computer the arrow keys pretend to tilt it. Tilt left/right and the box rolls.","achievement":"Achievement unlocks a badge once and shows a toast (“already” fires if it was earned before). Press Space.","ad":"Ad shows an interstitial, rewarded or banner ad (house ads built in; plug in your own provider). Space shows one.","alert":"Alert shows a pop-up message (toast or modal) – success, warning, error… Press Space to see it.","alpha":"Alpha sets how see-through an object is (0 invisible – 1 solid). Space fades the box to 25 %.","alternate":"Alternate (plugin) sends each signal to “a”, then “b”, then “a” again. Space flips the box between green and red.","always":"Always runs every frame while it is enabled. Here it feeds a Spin block, so the box turns without any input.","alwaysSwitch":"Always (switch) fires every frame while it is on. E switches it on (the box spins), D switches it off.","animation":"Animation plays a sprite animation – or a ready-made preset like bounce or pulse that works on any object. Space starts “pulse”.","arDistance":"AR Distance measures how far an object is from the camera (or from another object) and tells you when it is near.","arLight":"AR Light reads how bright the room is from the camera and lights the 3D objects to match.","arMode":"AR Mode starts augmented reality: the camera behind the game (or WebXR on supported phones). Press “Start AR”.","arPlace":"AR Place puts an object where you tap on the surface (move the object, or spawn copies). Tap the screen to place the box.","arScale":"AR Scale lets the player resize and turn an object with two fingers (pinch to zoom, twist to rotate).","arShadowFloor":"AR Shadow Floor adds an invisible floor that only shows shadows, so virtual objects look like they sit on the real surface.","arSurface":"AR Surface finds the floor / table and shows a reticle where you are pointing; it sends the hit position.","attacher":"Attach glues another object to this one so they move together. The box bumps into the ball, attaches it (target “other”) and drags it back.","bar":"Bar draws a progress / health bar from a variable (here “health”, max 100). Each press takes 20 off.","blending":"Blending changes how colours mix with what is behind: normal, add (glow), multiply, screen. Space switches the circle to “add”.","bluetoothConnect":"Bluetooth Connect pairs with a Bluetooth Low Energy device – the browser shows its own picker, so start it from a key or click. Space connects (a demo band stands in here).","bluetoothNotify":"Bluetooth Notify listens while the device pushes values by itself – here a heart-rate stream. Space connects and starts listening.","bluetoothRead":"Bluetooth Read asks a connected device for one value – here the battery level. Space connects, then reads it.","bluetoothWrite":"Bluetooth Write sends a value to a device (an LED, a motor…). Space connects, then writes the number 128.","bundle":"A Bundle packs several blocks into one reusable block. This one doubles its input: 21 goes in, 42 comes out. Double-click a bundle to open it.","bundleInput":"Inside a bundle, New Input creates an input socket (here “in1”) on the outside of the bundle. What arrives there comes out of this block.","bundleOutput":"Inside a bundle, New Output creates an output socket (here “out1”). Whatever you send into it leaves the bundle there.","calendar":"Calendar reads the real clock – date, time, weekday, hour… Here it shows the current time, refreshed every second.","camera":"Camera moves, zooms, follows or shakes the view. Press Space for a screen shake (also: follow, zoom, look-at in 3D).","cameraFeed":"Camera Feed shows the webcam in the corner, as an overlay or behind the game (here: corner).","caseSwitch":"Case Switch sends the signal out of the output whose name matches the value (cases “a, b, c”). Here “b” takes the middle path.","clampnum":"Clamp Number (plugin) keeps a number between a minimum and maximum. Random 0–100 values are squeezed into 20–60.","clipboard":"Clipboard copies text to the clipboard (or pastes it back – action “paste”). Space copies “Hello!”.","clock":"Clock is a stopwatch, countdown or real-time clock. Here a countdown from 10 starts automatically and shows mm:ss.","cloud":"Cloud saves and loads your game online with the player’s account (sign in first). Here it reports whether the player is signed in.","coinflip":"Coin Flip (plugin) sends a signal out of “heads” or “tails” at random. Press Space: heads turns the box green, tails red.","collision":"Collision fires when this object touches another – set “With” to a tag or name. Here the box slides into a wall.","colorTracker":"Color Tracker finds a colour in the webcam image and follows it (position and size). Hold a coloured object up to steer.","colors":"Colors changes an object’s colour – set a colour, blend toward it, shift the hue or pick randomly. Space picks a random colour.","controller":"Controller listens to a gamepad button or stick (here button 0 = A / Cross). Plug in a pad and press it.","cooldown":"Cooldown (plugin) lets one signal through, then blocks new ones for a while. Quick presses: first green, second red (too soon), later one green again.","counter":"Counter (plugin) counts signals and fires “reached” at its target. Three Space presses count to 3, then the box turns green.","cursor":"Cursor replaces the mouse pointer with a ring, cross, emoji or your own image while playing.","custom":"Custom Trigger runs your own JavaScript: call fire(value) whenever you want to send a signal. Here it fires every 0.8 s.","customBehavior":"Custom Block runs your own JavaScript on every incoming signal; “value” is the signal, return the answer. Here it squares 4.","destroyer":"Destroy removes an object (optionally with a burst). Press Space and the box pops.","deviceCheck":"Device Check asks about the device – mobile, tablet, iOS, touch, landscape, dark mode… and sends yes or no.","displayOrder":"Display Order decides which object is drawn in front. Press Space to bring the blue box in front of the red one.","ease":"Ease turns “start” into a smooth 0 → 1 curve (here quadOut over 1 s). Wired to Alpha, the box fades smoothly instead of jumping.","emit":"Emit Particles shoots a burst of particles (colour, speed, spread, life…). Press Space for a burst from the box.","enabled":"Enabled switches an object on or off (hidden, no physics, no logic). Space toggles the other box on and off.","exitGame":"Exit Game closes the game window / app (with a goodbye message). Space asks to quit.","expression":"Expression calculates a formula from its inputs a, b, c … Here a * 2 + 1 with a = 5 gives 11.","extractor":"Extractor reads a property of an object (x, y, angle, size…) and sends it out. Press Space to read the box’s x.","faceTracker":"Face Tracker finds a face in the webcam image and sends its position and size (needs a browser with face detection).","fetchUrl":"Fetch URL loads data from the web (GET/POST) and sends the result. Space fetches a GitHub “zen” quote.","filter":"Filter lets a signal through only if it passes a test. Here only random numbers above 50 get through to “pass”.","flip":"Flip mirrors an object horizontally and/or vertically. The arrow flips left ↔ right with each Space press.","fullScreen":"Full Screen enters or leaves full-screen mode (a browser needs a click or key to allow it). Space toggles it.","gameCenter":"Game Center (Apple) / Play Games (Google) sign-in, scores and achievements. On a computer it reports that it is not available.","gamePhysics":"Game Physics changes the world: gravity, time scale (slow motion), debug view. Space switches gravity on – the box falls.","gameSave":"Game Save stores the whole game state in a slot and restores it. Right moves the box, S saves, L loads – the box jumps back.","gesture":"Gesture recognises a swipe, tap, double tap or pinch with mouse or finger. A swipe left pushes the box left.","getField":"Get Field picks one value out of a signal that carries several. Size sends width + height together; Get Field “w” takes just the width (here 90).","globalVariable":"Global Variable stores a value any object can read. Each Space press adds 1 to “score”; its out port sends the new value.","hearing":"Hearing lets an object react to noises: it faces and walks toward the source and remembers it. This Guard hears the box when M is pressed.","impulse":"Impulse gives an object a sudden push – the classic jump. Press Space to kick the box upward.","inView":"In View fires when the object enters or leaves the camera view. Here the box slides off the right edge.","inrange":"In Range (plugin) checks whether a number lies between a minimum and maximum. Random 0–20 values: 5–15 turns the box green, others red.","joint":"Joint ties this object to an anchor like a rope or spring (distance + stiffness). Press Space to hang the box from the anchor – it swings.","joystick":"Joystick adds an on-screen stick for phones and tablets (it holds W A S D or arrow keys). Drag it – the box follows. Move it in the UI layer.","keyboard":"Keyboard fires when a key is pressed (down), released (up) or held. Set “Key” to the key you want – here Space.","label":"Label draws text on the screen (HUD). Use {variable} to show live values – each Space press adds 1 to the score.","leaderboard":"Leaderboard submits scores and shows the top list. Space submits 120 points, L shows the board.","level":"Level tells you about the current level: its number, name and how many there are – or marks it complete.","light":"Light changes a light source’s brightness and colour. Space makes the lamp brighter and warmer.","lightSensor":"Light Sensor measures how bright the webcam image is and tells you when it gets dark or bright.","listCount":"List Count tells you how many items a list has (all, numbers only or unique) and whether it is empty.","listEach":"List Each walks through a list one item at a time (every 0.5 s here) – “item” fires for each one, then “done”.","listModify":"List Modify adds, removes, inserts or replaces items in a named list. Each Space adds “kiwi” to the fruit list.","listOrder":"List Order sorts, shuffles, reverses or picks a random item from a list. Here it sorts the fruit A → Z.","loadLevel":"Load Level switches to another scene (“next”, a name or a number). Press Space to go to level 2.","lockedMouse":"Locked Mouse captures the mouse (click the game) and sends how far it moved (dx, dy) – the basis of mouse-look in first-person games.","logicGate":"Logic Gate combines two true/false inputs. With AND, the “true” output fires only when both A and B were pressed.","mailbox":"Mailbox receives messages sent by a Message block (here on the channel “hello”), from any object or scene.","makeNoise":"Make Noise sends a noise out from an object (footsteps or one-off). Press M to make noise – the Guard goes to where it came from.","mapnum":"Map Range (plugin) converts a number from one range to another. Space sends 75 (of 0–100) and gets 7.5 on a 0–10 scale.","material":"Material changes how a 3D object looks: colour, metalness, roughness, glow, texture, opacity. Space turns the cube shiny red.","message":"Message sends a text/value to other objects (target + channel). Here the box sends “hello”; the green Friend has a Mailbox that reacts.","microphone":"Microphone listens to the mic and sends the loudness (0–100) and pitch; “loud” fires above a limit. Here the level is shown live – press M to fake a loud sound.","modelAnimation":"Model Animation plays the clips stored inside a 3D model (skeleton + animation, Draco-compressed here). Space starts “Wave”, N switches to “Nod”; the block also tells which clips exist.","motionSensor":"Motion Sensor detects movement in the webcam image: how much, where (x, y) and swipe directions. The number rises as the picture moves.","mouseClick":"Mouse Click fires when the mouse button is clicked – anywhere, or only on this object (set “On” to self). It also sends the click position.","mouseMove":"Mouse Move sends the pointer position as it moves. Feed it into Position (source: signalXY) and the box follows the mouse.","mouseWheel":"Mouse Wheel sends “up” or “down” when you scroll. Here scrolling up grows the box and down shrinks it.","number":"Number outputs a fixed value whenever a signal arrives. Use it to turn “something happened” into a number.","numberList":"Number List makes a list of numbers – typed out or a range. Here 1 to 5 step 1.","objectVariable":"Object Variable is a value that belongs to one object (like “health”). Each press subtracts 10 from this box’s health.","once":"Once fires a single time when the game starts (after its delay) and sends 1 from its output. Nothing to connect – the label shows what it sent.","onceGate":"Once (gate) lets only the first signal through. Press Space three times – only the first one gets to the label.","pauseGame":"Pause Game freezes or resumes the game (toggle / pause / resume). Press P: the spinning box stops, press again to continue.","photoSnap":"Photo Snap takes a picture from the webcam (with a flash) and stores it in a variable or downloads it. Space = click!","physics":"Physics gives an object a body: gravity, bounce, friction, collisions. Press Space to make the box dynamic – it falls and bounces.","pointAt":"Point At turns an object to face a target – here the mouse. Move the pointer and the arrow follows.","position":"Position moves an object: “set” jumps to x/y, “add” moves by an amount; with a duration it glides smoothly. Press Space to slide 200 px right.","proximity":"Proximity fires when another object comes within a radius (here 150 px of the player). Great for doors, enemies and pick-ups.","pushMotor":"Push Motor keeps pushing an object in a direction (speed or acceleration). Press Space to start the engine.","random":"Random sends a random number (here 0–100, whole numbers) or makes a chance decision. Press Space for a new value.","randomcolor":"Random Color (plugin) sends a random bright colour as text. Each Space press shows a new one.","randompick":"Random Pick (plugin) sends a random line from your list. Each Space press shows a different cheer.","rayCast":"Ray Cast shoots an invisible line and reports what it hits and how far. Press Space: the ray goes right, hits the wall and sends the distance.","repeater":"Repeater turns one signal into several (count 4, every 0.3 s) – handy for bursts, volleys or retries.","restartGame":"Restart Game starts the scene (or whole game) again. The box drifts away; Space brings everything back to the start.","rotation":"Rotation turns an object to an angle (set) or by an angle (add), optionally smoothly. Space turns the box 90°.","roundnum":"Round (plugin) rounds to a number of decimals. Space sends 3.14159 and gets 3.14.","router":"Router sends a signal to one of several outputs – here round-robin: each press goes to the next colour.","saveValue":"Save Value stores a value on this device (a high score…) and loads it back later. S saves 99, L loads it.","sensor":"Sensor watches any value – a position, a variable – and fires when it crosses a limit. Here: when x is greater than 650.","sequencer":"Sequencer (plugin) steps through its outputs one signal at a time. Each Space press moves the box to the next colour.","shader":"Shader applies a screen / object effect (grayscale, blur, glitch, wavy, pixelize…). Space turns on “wavy”.","shake":"Shake fires when the phone is shaken (on a computer press H to test). Use it for “shake to reset” or dice rolls.","size":"Size changes width / height (/ depth in 3D) – set, add or multiply, instantly or smoothly. Space doubles the box.","smoothnum":"Smooth (plugin) glides toward the newest number instead of jumping. Space sends 100 and the value eases up.","sound":"Sound plays a sound (or stops / mutes it). Add sounds in the Assets tab; here the box pulses while it plays.","soundDetector":"Sound Detector recognises claps, double claps, whistles, shouts and silence from the microphone.","spawn":"Spawn creates copies of a template object (here “Coin”). Each press spawns one that flies up.","spin":"Spin turns an object around an axis continuously (degrees per second). Space starts a 180°/s spin.","spinMotor":"Spin Motor turns an object continuously (degrees per second). With “autoStart” it spins from the moment the game starts.","stopwatch":"Stopwatch (plugin) counts seconds while running (Auto start is on here).","switch":"Switch is a gate: signals pass only while it is on. A turns it off, S turns it on – Space only works while it is on.","text":"Text builds a string; {value} is replaced by the incoming signal. Here the number 5 becomes “Score: 5!”.","textCase":"Text Case converts upper/lower/title/camel/snake case. “hello big world” becomes “HELLO BIG WORLD”.","textCompare":"Text Compare tests two texts (equals, contains, starts with, regex…) and sends true or false.","textLength":"Text Length counts characters, words or lines. “The quick brown fox” has 4 words.","textList":"Text List splits text into a list (one item per line or by a separator) and sends it plus the count.","textSanitize":"Text Sanitize cleans user text: trim, collapse spaces, strip HTML, limit length. “  <b>Hi</b>   there ” → “Hi there”.","timer":"Timer sends a signal every “interval” seconds (here 0.8 s). Wire it to anything that should repeat.","toNumber":"To Number turns text into a number (or sends “invalid”). “42 coins” → 42, symbols stripped.","toggleSwitch":"Toggle Switch sends “in” to out1 or out2; “next” flips which one. Each press goes out, then flips – the box alternates red / blue.","touchButton":"Touch Button is an on-screen button that presses a key (here Space). Tap it and the keyboard trigger fires.","touchCheck":"Touch Check detects fingers on the screen – touching, how many, or touching this object. While held, the box turns green.","touchLook":"Touch Look turns a drag (or a look-stick) into camera movement – “dx / dy” show how far you dragged. In 3D it feeds the camera look.","typewriter":"Typewriter (plugin) types text one letter at a time. Space starts it.","userInfo":"User Info reads facts about the player’s device: platform, language, screen size, dark mode, time zone… Space shows the platform.","velocity":"Velocity sets or changes how fast an object moves (px/s). Space sends the box flying right; pressing again sets it back.","vibrate":"Vibrate buzzes the phone (a pattern in milliseconds, e.g. 150 or 100,50,100). The flash stands in for the buzz here.","voiceCommand":"Voice Command listens for spoken words (“jump”, “fire”…). Say one – or here press Space to send “jump” as if you said it.","voiceNoise":"Voice Noise turns your voice (or a test key, M) into noise other objects can hear. Press M: the red Guard hears it and walks over.","vrController":"VR Controller tracks a hand controller – trigger, grip, A / B, stick and position – and can attach an object to the hand. Here the mouse is the right hand.","vrGaze":"VR Gaze fires when the player looks at an object for a moment (here 1 s) – selection without controllers, ideal for cardboard viewers.","vrGrab":"VR Grab lets a hand pick up objects with the grip button (here anything tagged “grab”) and throw them when released.","vrHaptic":"VR Haptic buzzes a controller (strength + length). Press Space – on a headset your hand feels it.","vrHead":"VR Head follows the player’s head: position, turning (yaw/pitch/roll) and nod / shake gestures. Turn your head (here the arrow keys) and the number changes.","vrMode":"VR Mode adds the “Enter VR” button and switches to a headset (WebXR) or split-screen view (cardboard / computer).","vrMove":"VR Move walks the player around (smooth, snap-turn or teleport) with the controller stick. In the computer fallback use W A S D.","wrapnum":"Wrap (plugin) loops a number around a range. Space sends 370 into a 0–360 wrap and gets 10."};
